/****** Object:  StoredProcedure [dbo].[ConsultarAseguradoras]    Script Date: 3/11/2026 18:09:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[ConsultarAseguradoras] @IdAseguradora int = NULL, @IdUsuario int = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT IdAseguradora, IdUsuario, CedulaJuridica, Nombre, Telefono, Correo FROM dbo.Aseguradora
    WHERE (@IdAseguradora IS NULL OR IdAseguradora = @IdAseguradora)
      AND (@IdUsuario IS NULL OR IdUsuario = @IdUsuario) ORDER BY IdAseguradora;
END;
GO
/****** Object:  StoredProcedure [dbo].[ConsultarAuditorias]    Script Date: 3/11/2026 18:09:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[ConsultarAuditorias]
    @IdAuditoria int = NULL, @Tabla varchar(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT t.IdAuditoria, t.Tabla, t.Accion, t.Usuario, t.Fecha
    FROM dbo.Auditoria t 
    WHERE (@IdAuditoria IS NULL OR t.IdAuditoria=@IdAuditoria) AND (@Tabla IS NULL OR t.Tabla=@Tabla)
    ORDER BY t.IdAuditoria;
END;
GO
