CREATE   PROCEDURE [dbo].[ConsultarDetallesVenta]
    @IdDetalle int = NULL, @IdVenta int = NULL, @IdUsuario int = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT t.IdDetalle, t.IdVenta, t.IdRepuesto, t.IdBodega, t.Cantidad, t.Precio, CASE WHEN @IdUsuario IS NULL THEN t.Costo ELSE NULL END AS Costo
    FROM dbo.DetalleVenta t JOIN dbo.Venta v ON v.IdVenta=t.IdVenta JOIN dbo.Cotizacion co ON co.IdCotizacion=v.IdCotizacion JOIN dbo.Caso c ON c.IdCaso=co.IdCaso JOIN dbo.Aseguradora a ON a.IdAseguradora=c.IdAseguradora
    WHERE (@IdDetalle IS NULL OR t.IdDetalle=@IdDetalle) AND (@IdVenta IS NULL OR t.IdVenta=@IdVenta) AND (@IdUsuario IS NULL OR a.IdUsuario=@IdUsuario)
    ORDER BY t.IdDetalle;
END;
