SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[MantenimientoAseguradora]
    @function int, @IdAseguradora int = NULL, @IdUsuario int = NULL,
    @CedulaJuridica varchar(20) = NULL, @Nombre nvarchar(100) = NULL,
    @Telefono varchar(15) = NULL, @Correo varchar(100) = NULL,
    @CambiarTelefono bit = 0, @CambiarCorreo bit = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1, 2, 3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2, 3) AND (@IdAseguradora IS NULL OR @IdAseguradora <= 0) THROW 51102, 'ID invalido.', 1;
    IF @IdUsuario IS NOT NULL AND @IdUsuario <= 0 THROW 51102, 'Usuario invalido.', 1;
    IF @CedulaJuridica IS NOT NULL AND NULLIF(LTRIM(RTRIM(@CedulaJuridica)), '') IS NULL THROW 51102, 'Cedula vacia.', 1;
    IF @Nombre IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Nombre)), N'') IS NULL THROW 51102, 'Nombre vacio.', 1;
    IF @Telefono IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Telefono)), '') IS NULL THROW 51102, 'Telefono vacio.', 1;
    IF @Correo IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Correo)), '') IS NULL THROW 51102, 'Correo vacio.', 1;
    IF @function = 1
    BEGIN
        IF @IdUsuario IS NULL OR @CedulaJuridica IS NULL OR @Nombre IS NULL THROW 51102, 'Faltan datos requeridos.', 1;
        INSERT INTO dbo.Aseguradora(IdUsuario, CedulaJuridica, Nombre, Telefono, Correo)
        VALUES (@IdUsuario, @CedulaJuridica, @Nombre, @Telefono, @Correo);
        SELECT CAST(SCOPE_IDENTITY() AS int) AS IdAseguradora;
        RETURN;
    END;
    IF @function = 2
    BEGIN
        IF @IdUsuario IS NULL AND @CedulaJuridica IS NULL AND @Nombre IS NULL AND @Telefono IS NULL
            AND @Correo IS NULL AND ISNULL(@CambiarTelefono, 0) = 0 AND ISNULL(@CambiarCorreo, 0) = 0
            THROW 51102, 'Debe indicar cambios.', 1;
        UPDATE dbo.Aseguradora SET IdUsuario = ISNULL(@IdUsuario, IdUsuario),
            CedulaJuridica = ISNULL(@CedulaJuridica, CedulaJuridica), Nombre = ISNULL(@Nombre, Nombre),
            Telefono = CASE WHEN @CambiarTelefono = 1 THEN @Telefono ELSE ISNULL(@Telefono, Telefono) END,
            Correo = CASE WHEN @CambiarCorreo = 1 THEN @Correo ELSE ISNULL(@Correo, Correo) END
        WHERE IdAseguradora = @IdAseguradora;
        IF @@ROWCOUNT = 0 THROW 51101, 'Registro inexistente.', 1;
        RETURN;
    END;
    DELETE FROM dbo.Aseguradora WHERE IdAseguradora = @IdAseguradora;
    IF @@ROWCOUNT = 0 THROW 51101, 'Registro inexistente.', 1;
END;
GO
