CREATE   PROCEDURE [dbo].[MantenimientoAuditoria]
    @function int, @IdAuditoria int = NULL, @Tabla varchar(50) = NULL, @Accion char(1) = NULL, @Usuario varchar(100) = NULL, @Fecha datetime = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1,2,3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2,3) AND (@IdAuditoria IS NULL OR @IdAuditoria <= 0) THROW 51102, 'ID invalido.', 1;
    IF @Tabla IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Tabla)), '') IS NULL THROW 51102, 'Tabla no puede estar vacio.', 1;
    IF @Accion IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Accion)), '') IS NULL THROW 51102, 'Accion no puede estar vacio.', 1;
    IF @Accion IS NOT NULL AND @Accion NOT IN ('I','U','D') THROW 51102, 'Accion invalido.', 1;
    IF @Usuario IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Usuario)), '') IS NULL THROW 51102, 'Usuario no puede estar vacio.', 1;
    IF @function=1 AND (@Tabla IS NULL OR @Accion IS NULL OR @Usuario IS NULL) THROW 51102, 'Faltan datos requeridos.', 1;
    IF @function=2 AND @Tabla IS NULL AND @Accion IS NULL AND @Usuario IS NULL AND @Fecha IS NULL THROW 51102, 'Debe indicar cambios.', 1;
    DECLARE @NuevoId int;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF @function=1
        BEGIN
            INSERT INTO dbo.Auditoria(Tabla, Accion, Usuario, Fecha) VALUES (@Tabla, @Accion, @Usuario, ISNULL(@Fecha,GETUTCDATE()));
            SET @NuevoId=CAST(SCOPE_IDENTITY() AS int);
        END;
        ELSE IF @function=2
        BEGIN
            UPDATE dbo.Auditoria SET Tabla=ISNULL(@Tabla,Tabla), Accion=ISNULL(@Accion,Accion), Usuario=ISNULL(@Usuario,Usuario), Fecha=ISNULL(@Fecha,Fecha) WHERE IdAuditoria=@IdAuditoria;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        ELSE
        BEGIN
            DELETE FROM dbo.Auditoria WHERE IdAuditoria=@IdAuditoria;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        COMMIT TRANSACTION;
        IF @function=1 SELECT @NuevoId AS IdAuditoria;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
