CREATE   PROCEDURE [dbo].[MantenimientoCotizacion]
    @function int, @IdCotizacion int = NULL, @IdCaso int = NULL, @IdEmpleado int = NULL, @Fecha datetime = NULL, @Estado varchar(15) = NULL, @Total decimal(12,2) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1,2,3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2,3) AND (@IdCotizacion IS NULL OR @IdCotizacion <= 0) THROW 51102, 'ID invalido.', 1;
    IF @IdCaso IS NOT NULL AND @IdCaso <= 0 THROW 51102, 'IdCaso debe ser positivo.', 1;
    IF @IdEmpleado IS NOT NULL AND @IdEmpleado <= 0 THROW 51102, 'IdEmpleado debe ser positivo.', 1;
    IF @Estado IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Estado)), '') IS NULL THROW 51102, 'Estado no puede estar vacio.', 1;
    IF @Estado IS NOT NULL AND @Estado NOT IN ('Pendiente','Aprobada','Rechazada') THROW 51102, 'Estado invalido.', 1;
    IF @function IN (1,2) AND @Total IS NOT NULL THROW 51102, 'Total es calculado por los detalles.', 1;
    IF @function=1 AND (@IdCaso IS NULL OR @IdEmpleado IS NULL OR @Estado IS NULL) THROW 51102, 'Faltan datos requeridos.', 1;
    IF @function=2 AND @IdCaso IS NULL AND @IdEmpleado IS NULL AND @Fecha IS NULL AND @Estado IS NULL THROW 51102, 'Debe indicar cambios.', 1;
    DECLARE @NuevoId int;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF @function=1
        BEGIN
            INSERT INTO dbo.Cotizacion(IdCaso, IdEmpleado, Fecha, Estado, Total) VALUES (@IdCaso, @IdEmpleado, ISNULL(@Fecha,GETUTCDATE()), @Estado, 0);
            SET @NuevoId=CAST(SCOPE_IDENTITY() AS int);
        END;
        ELSE IF @function=2
        BEGIN
            UPDATE dbo.Cotizacion SET IdCaso=ISNULL(@IdCaso,IdCaso), IdEmpleado=ISNULL(@IdEmpleado,IdEmpleado), Fecha=ISNULL(@Fecha,Fecha), Estado=ISNULL(@Estado,Estado) WHERE IdCotizacion=@IdCotizacion;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        ELSE
        BEGIN
            DELETE FROM dbo.Cotizacion WHERE IdCotizacion=@IdCotizacion;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        COMMIT TRANSACTION;
        IF @function=1 SELECT @NuevoId AS IdCotizacion;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
