CREATE   PROCEDURE [dbo].[MantenimientoDetalleCotizacion]
    @function int, @IdDetalle int = NULL, @IdCotizacion int = NULL, @IdRepuesto int = NULL, @Cantidad int = NULL, @Precio decimal(10,2) = NULL, @Estado varchar(15) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1,2,3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2,3) AND (@IdDetalle IS NULL OR @IdDetalle <= 0) THROW 51102, 'ID invalido.', 1;
    IF @IdCotizacion IS NOT NULL AND @IdCotizacion <= 0 THROW 51102, 'IdCotizacion debe ser positivo.', 1;
    IF @IdRepuesto IS NOT NULL AND @IdRepuesto <= 0 THROW 51102, 'IdRepuesto debe ser positivo.', 1;
    IF @Cantidad IS NOT NULL AND @Cantidad <= 0 THROW 51102, 'Cantidad debe ser positivo.', 1;
    IF @Precio IS NOT NULL AND @Precio < 0 THROW 51102, 'Precio no puede ser negativo.', 1;
    IF @Estado IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Estado)), '') IS NULL THROW 51102, 'Estado no puede estar vacio.', 1;
    IF @Estado IS NOT NULL AND @Estado NOT IN ('Pendiente','Aprobado','Rechazado') THROW 51102, 'Estado invalido.', 1;
    IF @function=1 AND (@IdCotizacion IS NULL OR @IdRepuesto IS NULL OR @Cantidad IS NULL OR @Precio IS NULL OR @Estado IS NULL) THROW 51102, 'Faltan datos requeridos.', 1;
    IF @function=2 AND @IdCotizacion IS NULL AND @IdRepuesto IS NULL AND @Cantidad IS NULL AND @Precio IS NULL AND @Estado IS NULL THROW 51102, 'Debe indicar cambios.', 1;
    DECLARE @NuevoId int;
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @PadreAnterior int, @PadreNuevo int, @Bloqueo int;
        IF @function IN (2,3)
        BEGIN
            SELECT @PadreAnterior=IdCotizacion FROM dbo.DetalleCotizacion WITH (UPDLOCK,HOLDLOCK) WHERE IdDetalle=@IdDetalle;
            IF @PadreAnterior IS NULL THROW 51101, 'Registro inexistente.', 1;
        END;
        SET @PadreNuevo=CASE WHEN @function=3 THEN NULL ELSE ISNULL(@IdCotizacion,@PadreAnterior) END;
        SELECT @Bloqueo=IdCotizacion FROM dbo.Cotizacion WITH (UPDLOCK,HOLDLOCK)
        WHERE IdCotizacion IN (@PadreAnterior,@PadreNuevo) ORDER BY IdCotizacion;
        IF @function=1
        BEGIN
            INSERT INTO dbo.DetalleCotizacion(IdCotizacion, IdRepuesto, Cantidad, Precio, Estado) VALUES (@IdCotizacion, @IdRepuesto, @Cantidad, @Precio, @Estado);
            SET @NuevoId=CAST(SCOPE_IDENTITY() AS int);
        END;
        ELSE IF @function=2
        BEGIN
            UPDATE dbo.DetalleCotizacion SET IdCotizacion=ISNULL(@IdCotizacion,IdCotizacion), IdRepuesto=ISNULL(@IdRepuesto,IdRepuesto), Cantidad=ISNULL(@Cantidad,Cantidad), Precio=ISNULL(@Precio,Precio), Estado=ISNULL(@Estado,Estado) WHERE IdDetalle=@IdDetalle;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        ELSE
        BEGIN
            DELETE FROM dbo.DetalleCotizacion WHERE IdDetalle=@IdDetalle;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        COMMIT TRANSACTION;
        IF @function=1 SELECT @NuevoId AS IdDetalle;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
