/****** Object:  StoredProcedure [dbo].[MantenimientoDetalleVenta]    Script Date: 3/11/2026 18:09:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[MantenimientoDetalleVenta]
    @function int, @IdDetalle int = NULL, @IdVenta int = NULL, @IdRepuesto int = NULL, @IdBodega int = NULL, @Cantidad int = NULL, @Precio decimal(10,2) = NULL, @Costo decimal(10,2) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1,2,3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2,3) AND (@IdDetalle IS NULL OR @IdDetalle <= 0) THROW 51102, 'ID invalido.', 1;
    IF @IdVenta IS NOT NULL AND @IdVenta <= 0 THROW 51102, 'IdVenta debe ser positivo.', 1;
    IF @IdRepuesto IS NOT NULL AND @IdRepuesto <= 0 THROW 51102, 'IdRepuesto debe ser positivo.', 1;
    IF @IdBodega IS NOT NULL AND @IdBodega <= 0 THROW 51102, 'IdBodega debe ser positivo.', 1;
    IF @Cantidad IS NOT NULL AND @Cantidad <= 0 THROW 51102, 'Cantidad debe ser positivo.', 1;
    IF @Precio IS NOT NULL AND @Precio < 0 THROW 51102, 'Precio no puede ser negativo.', 1;
    IF @Costo IS NOT NULL AND @Costo < 0 THROW 51102, 'Costo no puede ser negativo.', 1;
    IF @function=1 AND (@IdVenta IS NULL OR @IdRepuesto IS NULL OR @IdBodega IS NULL OR @Cantidad IS NULL OR @Precio IS NULL OR @Costo IS NULL) THROW 51102, 'Faltan datos requeridos.', 1;
    IF @function=2 AND @IdVenta IS NULL AND @IdRepuesto IS NULL AND @IdBodega IS NULL AND @Cantidad IS NULL AND @Precio IS NULL AND @Costo IS NULL THROW 51102, 'Debe indicar cambios.', 1;
    DECLARE @NuevoId int;
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @PadreAnterior int, @PadreNuevo int, @Bloqueo int;
        DECLARE @BodegaAnterior int, @RepuestoAnterior int, @CantidadAnterior int;
        IF @function IN (2,3)
        BEGIN
            SELECT @PadreAnterior=IdVenta, @BodegaAnterior=IdBodega, @RepuestoAnterior=IdRepuesto, @CantidadAnterior=Cantidad FROM dbo.DetalleVenta WITH (UPDLOCK,HOLDLOCK) WHERE IdDetalle=@IdDetalle;
            IF @PadreAnterior IS NULL THROW 51101, 'Registro inexistente.', 1;
        END;
        SET @PadreNuevo=CASE WHEN @function=3 THEN NULL ELSE ISNULL(@IdVenta,@PadreAnterior) END;
        SELECT @Bloqueo=IdVenta FROM dbo.Venta WITH (UPDLOCK,HOLDLOCK)
        WHERE IdVenta IN (@PadreAnterior,@PadreNuevo) ORDER BY IdVenta;
        DECLARE @BodegaNueva int=CASE WHEN @function=3 THEN NULL ELSE ISNULL(@IdBodega,@BodegaAnterior) END,
                @RepuestoNuevo int=CASE WHEN @function=3 THEN NULL ELSE ISNULL(@IdRepuesto,@RepuestoAnterior) END,
                @CantidadNueva int=ISNULL(@Cantidad,@CantidadAnterior), @Disponible bigint=0;
        SELECT @Bloqueo=IdInventario FROM dbo.Inventario WITH (UPDLOCK,HOLDLOCK)
        WHERE (IdBodega=@BodegaAnterior AND IdRepuesto=@RepuestoAnterior)
           OR (IdBodega=@BodegaNueva AND IdRepuesto=@RepuestoNuevo)
        ORDER BY IdBodega, IdRepuesto;
        IF @function IN (1,2)
        BEGIN
            SELECT @Disponible=Cantidad FROM dbo.Inventario WHERE IdBodega=@BodegaNueva AND IdRepuesto=@RepuestoNuevo;
            IF @function=2 AND @BodegaAnterior=@BodegaNueva AND @RepuestoAnterior=@RepuestoNuevo
                SET @Disponible=@Disponible+@CantidadAnterior;
            IF @Disponible < @CantidadNueva THROW 51103, 'Existencias insuficientes.', 1;
        END;
        IF @function=1
        BEGIN
            INSERT INTO dbo.DetalleVenta(IdVenta, IdRepuesto, IdBodega, Cantidad, Precio, Costo) VALUES (@IdVenta, @IdRepuesto, @IdBodega, @Cantidad, @Precio, @Costo);
            SET @NuevoId=CAST(SCOPE_IDENTITY() AS int);
        END;
        ELSE IF @function=2
        BEGIN
            UPDATE dbo.DetalleVenta SET IdVenta=ISNULL(@IdVenta,IdVenta), IdRepuesto=ISNULL(@IdRepuesto,IdRepuesto), IdBodega=ISNULL(@IdBodega,IdBodega), Cantidad=ISNULL(@Cantidad,Cantidad), Precio=ISNULL(@Precio,Precio), Costo=ISNULL(@Costo,Costo) WHERE IdDetalle=@IdDetalle;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        ELSE
        BEGIN
            DELETE FROM dbo.DetalleVenta WHERE IdDetalle=@IdDetalle;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        COMMIT TRANSACTION;
        IF @function=1 SELECT @NuevoId AS IdDetalle;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
