CREATE   PROCEDURE [dbo].[MantenimientoEmpleado]
    @function int, @IdEmpleado int = NULL, @IdUsuario int = NULL,
    @Cedula varchar(20) = NULL, @Nombre nvarchar(100) = NULL, @Puesto nvarchar(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1, 2, 3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2, 3) AND (@IdEmpleado IS NULL OR @IdEmpleado <= 0) THROW 51102, 'ID invalido.', 1;
    IF @IdUsuario IS NOT NULL AND @IdUsuario <= 0 THROW 51102, 'Usuario invalido.', 1;
    IF @Cedula IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Cedula)), '') IS NULL THROW 51102, 'Cedula vacia.', 1;
    IF @Nombre IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Nombre)), N'') IS NULL THROW 51102, 'Nombre vacio.', 1;
    IF @Puesto IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Puesto)), N'') IS NULL THROW 51102, 'Puesto vacio.', 1;
    IF @function = 1
    BEGIN
        IF @IdUsuario IS NULL OR @Cedula IS NULL OR @Nombre IS NULL OR @Puesto IS NULL
            THROW 51102, 'Faltan datos requeridos.', 1;
        INSERT INTO dbo.Empleado(IdUsuario, Cedula, Nombre, Puesto) VALUES (@IdUsuario, @Cedula, @Nombre, @Puesto);
        SELECT CAST(SCOPE_IDENTITY() AS int) AS IdEmpleado;
        RETURN;
    END;
    IF @function = 2
    BEGIN
        IF @IdUsuario IS NULL AND @Cedula IS NULL AND @Nombre IS NULL AND @Puesto IS NULL
            THROW 51102, 'Debe indicar cambios.', 1;
        UPDATE dbo.Empleado SET IdUsuario = ISNULL(@IdUsuario, IdUsuario), Cedula = ISNULL(@Cedula, Cedula),
            Nombre = ISNULL(@Nombre, Nombre), Puesto = ISNULL(@Puesto, Puesto) WHERE IdEmpleado = @IdEmpleado;
        IF @@ROWCOUNT = 0 THROW 51101, 'Registro inexistente.', 1;
        RETURN;
    END;
    DELETE FROM dbo.Empleado WHERE IdEmpleado = @IdEmpleado;
    IF @@ROWCOUNT = 0 THROW 51101, 'Registro inexistente.', 1;
END;
GO
