CREATE   PROCEDURE [dbo].[MantenimientoEnvio]
    @function int, @IdEnvio int = NULL, @IdVenta int = NULL, @Direccion nvarchar(200) = NULL, @Costo decimal(10,2) = NULL, @Estado varchar(15) = NULL, @FechaEntrega datetime = NULL, @CambiarFechaEntrega bit = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1,2,3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2,3) AND (@IdEnvio IS NULL OR @IdEnvio <= 0) THROW 51102, 'ID invalido.', 1;
    IF @IdVenta IS NOT NULL AND @IdVenta <= 0 THROW 51102, 'IdVenta debe ser positivo.', 1;
    IF @Direccion IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Direccion)), '') IS NULL THROW 51102, 'Direccion no puede estar vacio.', 1;
    IF @Costo IS NOT NULL AND @Costo < 0 THROW 51102, 'Costo no puede ser negativo.', 1;
    IF @Estado IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Estado)), '') IS NULL THROW 51102, 'Estado no puede estar vacio.', 1;
    IF @Estado IS NOT NULL AND @Estado NOT IN ('Pendiente','En camino','Entregado') THROW 51102, 'Estado invalido.', 1;
    IF @function=1 AND (@IdVenta IS NULL OR @Direccion IS NULL OR @Costo IS NULL OR @Estado IS NULL) THROW 51102, 'Faltan datos requeridos.', 1;
    IF @function=2 AND @IdVenta IS NULL AND @Direccion IS NULL AND @Costo IS NULL AND @Estado IS NULL AND @FechaEntrega IS NULL AND ISNULL(@CambiarFechaEntrega,0)=0 THROW 51102, 'Debe indicar cambios.', 1;
    DECLARE @NuevoId int;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF @function=1
        BEGIN
            INSERT INTO dbo.Envio(IdVenta, Direccion, Costo, Estado, FechaEntrega) VALUES (@IdVenta, @Direccion, @Costo, @Estado, @FechaEntrega);
            SET @NuevoId=CAST(SCOPE_IDENTITY() AS int);
        END;
        ELSE IF @function=2
        BEGIN
            UPDATE dbo.Envio SET IdVenta=ISNULL(@IdVenta,IdVenta), Direccion=ISNULL(@Direccion,Direccion), Costo=ISNULL(@Costo,Costo), Estado=ISNULL(@Estado,Estado), FechaEntrega=CASE WHEN @CambiarFechaEntrega=1 THEN @FechaEntrega ELSE ISNULL(@FechaEntrega,FechaEntrega) END WHERE IdEnvio=@IdEnvio;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        ELSE
        BEGIN
            DELETE FROM dbo.Envio WHERE IdEnvio=@IdEnvio;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        COMMIT TRANSACTION;
        IF @function=1 SELECT @NuevoId AS IdEnvio;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
