/****** Object:  StoredProcedure [dbo].[MantenimientoRol]    Script Date: 3/11/2026 18:09:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[MantenimientoRol]
    @function int, @IdRol int = NULL, @Nombre varchar(30) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1, 2, 3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2, 3) AND (@IdRol IS NULL OR @IdRol <= 0) THROW 51102, 'ID invalido.', 1;
    IF @function IN (1, 2) AND NULLIF(LTRIM(RTRIM(@Nombre)), '') IS NULL THROW 51102, 'Nombre requerido.', 1;
    IF @function = 1
    BEGIN
        INSERT INTO dbo.Rol(Nombre) VALUES (@Nombre);
        SELECT CAST(SCOPE_IDENTITY() AS int) AS IdRol;
        RETURN;
    END;
    IF @function = 2
    BEGIN
        UPDATE dbo.Rol SET Nombre = @Nombre WHERE IdRol = @IdRol;
        IF @@ROWCOUNT = 0 THROW 51101, 'Registro inexistente.', 1;
        RETURN;
    END;
    DELETE FROM dbo.Rol WHERE IdRol = @IdRol;
    IF @@ROWCOUNT = 0 THROW 51101, 'Registro inexistente.', 1;
END;
GO
