CREATE   PROCEDURE [dbo].[MantenimientoUsuario]
    @function int, @IdUsuario int = NULL, @IdRol int = NULL,
    @Correo varchar(100) = NULL, @Contrasena varchar(255) = NULL, @Activo bit = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1, 2, 3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2, 3) AND (@IdUsuario IS NULL OR @IdUsuario <= 0) THROW 51102, 'ID invalido.', 1;
    IF @IdRol IS NOT NULL AND @IdRol <= 0 THROW 51102, 'Rol invalido.', 1;
    IF @Correo IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Correo)), '') IS NULL THROW 51102, 'Correo vacio.', 1;
    IF @Contrasena IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Contrasena)), '') IS NULL THROW 51102, 'Hash vacio.', 1;
    IF @function = 1
    BEGIN
        IF @IdRol IS NULL OR @Correo IS NULL OR @Contrasena IS NULL THROW 51102, 'Faltan datos requeridos.', 1;
        INSERT INTO dbo.Usuario(IdRol, Correo, Contrasena, Activo)
        VALUES (@IdRol, @Correo, @Contrasena, ISNULL(@Activo, 1));
        SELECT CAST(SCOPE_IDENTITY() AS int) AS IdUsuario;
        RETURN;
    END;
    IF @function = 2
    BEGIN
        IF @IdRol IS NULL AND @Correo IS NULL AND @Contrasena IS NULL AND @Activo IS NULL
            THROW 51102, 'Debe indicar cambios.', 1;
        UPDATE dbo.Usuario SET IdRol = ISNULL(@IdRol, IdRol), Correo = ISNULL(@Correo, Correo),
            Contrasena = ISNULL(@Contrasena, Contrasena), Activo = ISNULL(@Activo, Activo)
        WHERE IdUsuario = @IdUsuario;
        IF @@ROWCOUNT = 0 THROW 51101, 'Registro inexistente.', 1;
        RETURN;
    END;
    DELETE FROM dbo.Usuario WHERE IdUsuario = @IdUsuario;
    IF @@ROWCOUNT = 0 THROW 51101, 'Registro inexistente.', 1;
END;
GO
/****** Object:  StoredProcedure [dbo].[MantenimientoVenta]    Script Date: 3/11/2026 18:09:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[MantenimientoVenta]
    @function int, @IdVenta int = NULL, @IdCotizacion int = NULL, @IdEmpleado int = NULL, @Fecha datetime = NULL, @Total decimal(12,2) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @function IS NULL OR @function NOT IN (1,2,3) THROW 51100, 'Operacion invalida.', 1;
    IF @function IN (2,3) AND (@IdVenta IS NULL OR @IdVenta <= 0) THROW 51102, 'ID invalido.', 1;
    IF @IdCotizacion IS NOT NULL AND @IdCotizacion <= 0 THROW 51102, 'IdCotizacion debe ser positivo.', 1;
    IF @IdEmpleado IS NOT NULL AND @IdEmpleado <= 0 THROW 51102, 'IdEmpleado debe ser positivo.', 1;
    IF @function IN (1,2) AND @Total IS NOT NULL THROW 51102, 'Total es calculado por los detalles.', 1;
    IF @function=1 AND (@IdCotizacion IS NULL OR @IdEmpleado IS NULL) THROW 51102, 'Faltan datos requeridos.', 1;
    IF @function=2 AND @IdCotizacion IS NULL AND @IdEmpleado IS NULL AND @Fecha IS NULL THROW 51102, 'Debe indicar cambios.', 1;
    DECLARE @NuevoId int;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF @function=1
        BEGIN
            INSERT INTO dbo.Venta(IdCotizacion, IdEmpleado, Fecha, Total) VALUES (@IdCotizacion, @IdEmpleado, ISNULL(@Fecha,GETUTCDATE()), 0);
            SET @NuevoId=CAST(SCOPE_IDENTITY() AS int);
        END;
        ELSE IF @function=2
        BEGIN
            UPDATE dbo.Venta SET IdCotizacion=ISNULL(@IdCotizacion,IdCotizacion), IdEmpleado=ISNULL(@IdEmpleado,IdEmpleado), Fecha=ISNULL(@Fecha,Fecha) WHERE IdVenta=@IdVenta;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        ELSE
        BEGIN
            DELETE FROM dbo.Venta WHERE IdVenta=@IdVenta;
            IF @@ROWCOUNT=0 THROW 51101, 'Registro inexistente.', 1;
        END;
        COMMIT TRANSACTION;
        IF @function=1 SELECT @NuevoId AS IdVenta;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[ObtenerCredencialLogin]    Script Date: 3/11/2026 18:09:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[ObtenerCredencialLogin]
    @Correo VARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    -- Una cuenta debe tener un unico perfil coherente antes de permitir el acceso.
    SELECT u.IdUsuario, u.Correo, u.Contrasena AS HashContrasena, r.Nombre AS Rol,
           e.IdEmpleado, a.IdAseguradora, COALESCE(e.Nombre, a.Nombre, u.Correo) AS Nombre
    FROM dbo.Usuario u
    JOIN dbo.Rol r ON r.IdRol = u.IdRol
    LEFT JOIN dbo.Empleado e ON e.IdUsuario = u.IdUsuario
    LEFT JOIN dbo.Aseguradora a ON a.IdUsuario = u.IdUsuario
    WHERE u.Correo = @Correo AND u.Activo = 1
      AND ((r.Nombre IN ('Administrador', 'Empleado')
            AND (SELECT COUNT(*) FROM dbo.Empleado WHERE IdUsuario = u.IdUsuario) = 1
            AND NOT EXISTS (SELECT 1 FROM dbo.Aseguradora WHERE IdUsuario = u.IdUsuario))
        OR (r.Nombre = 'Cliente'
            AND (SELECT COUNT(*) FROM dbo.Aseguradora WHERE IdUsuario = u.IdUsuario) = 1
            AND NOT EXISTS (SELECT 1 FROM dbo.Empleado WHERE IdUsuario = u.IdUsuario)));
END;

GO
